(function() {
    'use strict';

    class FairProcessAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = `Fair Process`;
            this.version = `1.1.0`;

            this.ROUNDS = [
                { id: 1, titleKey: `briefing_title_r1`, textKey: `briefing_text_r1`, panelId: `round1Panel`, nameKey: `round_name_r1`, clockKey: `clock_r1` },
                { id: 2, titleKey: `briefing_title_r2`, textKey: `briefing_text_r2`, panelId: `round2Panel`, nameKey: `round_name_r2`, clockKey: `clock_r2` },
                { id: 3, titleKey: `briefing_title_r3`, textKey: `briefing_text_r3`, panelId: `round3Panel`, nameKey: `round_name_r3`, clockKey: `clock_r3` },
                { id: 4, titleKey: `briefing_title_r4`, textKey: `briefing_text_r4`, panelId: `round4Panel`, nameKey: `round_name_r4`, clockKey: `clock_r4` }
            ];

            // The concept's truth: the leak destroyed trust through PROCESS, not the closure.
            this.TRUE_CAUSE = `process`;
            // The INVOLVE stages the leak actually skipped: engage, explore, explain.
            // (Execute & evaluate hadn't happened yet, so ticking them is over-claiming.)
            this.SKIPPED_STAGES = [`engage`, `explore`, `explain`];

            // The closure is SETTLED; ticking it as "open" is fair-process fraud.
            this.SETTLED = `closure`;

            // Targeted annual savings and the network-wide slip that can erase part of it.
            this.SAVINGS_TARGET = 14.0;   // EUR M
            this.SLIP_AT_RISK = 9.0;      // EUR M erased by a 5% output slip
            this.PACKAGE_CAP = 9.0;       // EUR M support-package input cap
            this.FAIRNESS_BASELINE = 62;  // prior baseline before the leak
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    fairness: 34,
                    commit: 40,
                    integrity: 30,
                    savings: 14.0,
                    freezeRisk: `high`,        // high | medium | low
                    engineersRetained: 0,
                    fraudCommitted: false,
                    overPromised: false,
                    packageSpent: 0,
                    fairnessHistory: [34],
                    commitHistory: [40],
                    integrityHistory: [30],
                    savingsHistory: [14.0],
                    coachMessages: [],
                    lastCoach: ``
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = {
                    cause: `process`,
                    stages: [],
                    honesty: 55,
                    depth: `calibrated`,
                    open: [],
                    honor: `visible`,
                    transparency: `full`,
                    sequence: `cse_first`,
                    tone: `clarity`,
                    package: 4,
                    retain: `role`,
                    evaluate: `loop`,
                    customer: `evidence`
                };
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            const state = window.mySimulation.state;
            const round = state.currentPeriod || 1;
            const warn = (k) => window.mySimulation.uiManager.showNotification(window.mySimulation.t(k), `warning`);

            if (round === 1) {
                const cause = document.getElementById(`causeInput`);
                const hon = document.getElementById(`honestyInput`);
                if (cause) decisions.cause = cause.value;
                const stageIds = [[`stEngage`, `engage`], [`stExplore`, `explore`], [`stExplain`, `explain`], [`stExecute`, `execute`], [`stEvaluate`, `evaluate`]];
                const picked = [];
                stageIds.forEach(([elId, val]) => {
                    const el = document.getElementById(elId);
                    if (el && el.checked) picked.push(val);
                });
                decisions.stages = picked;
                if (hon) decisions.honesty = parseInt(hon.value, 10);
                if (!Number.isFinite(decisions.honesty) || decisions.honesty < 0 || decisions.honesty > 100) {
                    warn(`warn_honesty_range`); return false;
                }
                if (picked.length === 0) {
                    warn(`warn_no_stages`); return false;
                }
            } else if (round === 2) {
                const depth = document.getElementById(`depthInput`);
                const honor = document.getElementById(`honorInput`);
                if (depth) decisions.depth = depth.value;
                if (honor) decisions.honor = honor.value;
                const openIds = [[`opTiming`, `timing`], [`opTerms`, `terms`], [`opSupport`, `support`], [`opClosure`, `closure`]];
                const picked = [];
                openIds.forEach(([elId, val]) => {
                    const el = document.getElementById(elId);
                    if (el && el.checked) picked.push(val);
                });
                decisions.open = picked;
            } else if (round === 3) {
                const tr = document.getElementById(`transparencyInput`);
                const seq = document.getElementById(`sequenceInput`);
                const tone = document.getElementById(`toneInput`);
                if (tr) decisions.transparency = tr.value;
                if (seq) decisions.sequence = seq.value;
                if (tone) decisions.tone = tone.value;
            } else if (round === 4) {
                const pkg = document.getElementById(`packageInput`);
                const ret = document.getElementById(`retainInput`);
                const ev = document.getElementById(`evaluateInput`);
                const cust = document.getElementById(`customerInput`);
                if (pkg) decisions.package = parseFloat(pkg.value);
                if (ret) decisions.retain = ret.value;
                if (ev) decisions.evaluate = ev.value;
                if (cust) decisions.customer = cust.value;
                if (!Number.isFinite(decisions.package) || decisions.package < 0 || decisions.package > this.PACKAGE_CAP) {
                    warn(`warn_package_range`); return false;
                }
            }
            return true;
        }

        calculateResults(state) {
            const d = state.decisions;
            const ds = state.domainState;
            const round = state.currentPeriod;

            let fairDelta = 0, commitDelta = 0, integrityDelta = 0, savingsDelta = 0;
            let coachKey = `coach_default`;
            let summaryKey = `sum_default`;

            if (round === 1) {
                // DIAGNOSE. The real cause is the process; everything else is misreading the gap.
                if (d.cause === this.TRUE_CAUSE) {
                    fairDelta += 6; integrityDelta += 14; coachKey = `coach_r1_cause_right`;
                } else if (d.cause === `union`) {
                    integrityDelta -= 10; fairDelta -= 4; coachKey = `coach_r1_cause_blame`;
                } else {
                    integrityDelta -= 6; coachKey = `coach_r1_cause_content`;
                }

                // INVOLVE diagnosis. The leak skipped engage, explore, explain — and ONLY those.
                const picks = d.stages || [];
                const correctHits = this.SKIPPED_STAGES.filter((s) => picks.indexOf(s) !== -1).length;
                const overClaim = picks.filter((s) => this.SKIPPED_STAGES.indexOf(s) === -1).length;
                if (correctHits === 3 && overClaim === 0) {
                    integrityDelta += 12; coachKey = (d.cause === this.TRUE_CAUSE) ? `coach_r1_diag_sharp` : coachKey;
                } else if (correctHits >= 2 && overClaim === 0) {
                    integrityDelta += 6;
                } else if (overClaim > 0) {
                    integrityDelta -= 4; coachKey = (d.cause === this.TRUE_CAUSE) ? `coach_r1_overclaim` : coachKey;
                } else {
                    integrityDelta -= 2;
                }

                // Honest ownership of the process failure — the precondition for everything after.
                if (d.honesty >= 60) { integrityDelta += 8; commitDelta += 2; }
                else if (d.honesty <= 25) { integrityDelta -= 8; coachKey = `coach_r1_denial`; }

                summaryKey = (d.cause === this.TRUE_CAUSE && correctHits === 3 && overClaim === 0) ? `sum_r1_good` : `sum_r1_weak`;
            } else if (round === 2) {
                // CALIBRATE ENGAGEMENT. The central tension: neither impose nor falsely democratise.
                const open = d.open || [];
                const openedClosure = open.indexOf(this.SETTLED) !== -1;   // fair-process fraud lever
                const openedReal = open.filter((o) => o !== this.SETTLED).length; // timing/terms/support

                switch (d.depth) {
                    case `calibrated`:
                        fairDelta += 12; commitDelta += 10; integrityDelta += 8; coachKey = `coach_r2_calibrated`; break;
                    case `none`:
                        fairDelta -= 12; commitDelta -= 8; integrityDelta -= 6; coachKey = `coach_r2_none`; break;
                    case `token`:
                        fairDelta -= 14; commitDelta -= 10; integrityDelta -= 12; coachKey = `coach_r2_token`; break;
                    case `full`:
                        fairDelta -= 8; commitDelta -= 6; integrityDelta -= 14; coachKey = `coach_r2_falsevote`; break;
                }

                // FAIR-PROCESS FRAUD: putting the settled closure "on the table" raises then crushes hope.
                if (openedClosure) {
                    ds.fraudCommitted = true;
                    fairDelta -= 12; commitDelta -= 8; integrityDelta -= 16; coachKey = `coach_r2_fraud`;
                } else if (openedReal >= 2) {
                    // Honest scoping of real decision rights builds genuine voice.
                    fairDelta += 8; commitDelta += 6; integrityDelta += 6;
                } else if (openedReal === 0 && d.depth === `calibrated`) {
                    // Says "calibrated" but opened nothing real = empty consultation.
                    fairDelta -= 6; integrityDelta -= 6; coachKey = `coach_r2_nothingopen`;
                }

                // DECORATIVE CONSULTATION: gathering input then ignoring it breaks trust twice.
                if (d.honor === `visible`) {
                    fairDelta += 8; commitDelta += 8; integrityDelta += 8;
                } else if (d.honor === `ignore`) {
                    fairDelta -= 14; commitDelta -= 10; integrityDelta -= 14; coachKey = (d.depth !== `none`) ? `coach_r2_decorative` : coachKey;
                } else if (d.honor === `partial`) {
                    fairDelta -= 2; commitDelta -= 2;
                }

                summaryKey = (d.depth === `calibrated` && !openedClosure && openedReal >= 2 && d.honor === `visible`) ? `sum_r2_good` : `sum_r2_weak`;
            } else if (round === 3) {
                // EXPLAIN & COMMUNICATE. Transparency, sequence, tone.
                switch (d.transparency) {
                    case `full`:
                        fairDelta += 12; commitDelta += 8; integrityDelta += 6; coachKey = `coach_r3_full`; break;
                    case `headline`:
                        fairDelta += 4; commitDelta += 2; coachKey = `coach_r3_headline`; break;
                    case `minimal`:
                        // Missing the why lets people invent worse stories.
                        fairDelta -= 12; commitDelta -= 8; integrityDelta -= 4; coachKey = `coach_r3_nowhy`; break;
                }

                // SEQUENCE. French law requires CSE information-and-consultation FIRST; skipping it
                // risks the 4–6 month legal freeze that takes the EUR 14M with it.
                switch (d.sequence) {
                    case `cse_first`:
                        fairDelta += 8; integrityDelta += 8; commitDelta += 4;
                        ds.freezeRisk = `low`; coachKey = (d.transparency === `full`) ? `coach_r3_cse` : coachKey; break;
                    case `all_hands`:
                        fairDelta -= 4; integrityDelta -= 6;
                        ds.freezeRisk = `medium`;
                        savingsDelta -= 2.0; coachKey = `coach_r3_allhands`; break;
                    case `press_first`:
                        // Briefing the press before staff/CSE is a procedural and legal own-goal.
                        fairDelta -= 14; commitDelta -= 10; integrityDelta -= 12;
                        ds.freezeRisk = `high`;
                        savingsDelta -= this.SAVINGS_TARGET * 0.45; coachKey = `coach_r3_press`; break;
                }

                // TONE. Clarity over comforting over-promises.
                switch (d.tone) {
                    case `clarity`:
                        fairDelta += 8; commitDelta += 8; integrityDelta += 8; coachKey = (coachKey === `coach_default`) ? `coach_r3_clarity` : coachKey; break;
                    case `reassure`:
                        // Over-promising no forced redundancies / full redeployment within 30km.
                        ds.overPromised = true;
                        fairDelta += 4; commitDelta -= 6; integrityDelta -= 12; coachKey = `coach_r3_overpromise`; break;
                    case `firm`:
                        // Firm-and-brief without warmth reads as another fait accompli.
                        fairDelta -= 6; commitDelta -= 4; coachKey = (coachKey === `coach_default`) ? `coach_r3_firm` : coachKey; break;
                }

                // Anxiety-driven output slip: low fairness so far still bleeds savings.
                if (ds.fairness + fairDelta < 45) {
                    savingsDelta -= 3.0;
                }

                summaryKey = (d.transparency !== `minimal` && d.sequence === `cse_first` && d.tone === `clarity`) ? `sum_r3_good` : `sum_r3_weak`;
            } else if (round === 4) {
                // SECURE COMMITMENT & EXECUTE. Package, retention, evaluate loop, customer.
                // The €14M is the ANNUAL run-rate saving; the support package is a one-off
                // transition cost, so it does not erode the annual figure 1:1. But over-spending
                // (>€7M) signals the consolidation's purpose is being given away — a modest drag.
                const pkg = d.package;
                ds.packageSpent = Math.round(pkg * 10) / 10;

                if (pkg >= 3 && pkg <= 6) {
                    fairDelta += 8; commitDelta += 10; coachKey = `coach_r4_package_right`;
                } else if (pkg < 2) {
                    // Too little support reads as abandonment.
                    fairDelta -= 8; commitDelta -= 8; coachKey = `coach_r4_package_thin`;
                } else if (pkg > 7) {
                    // Spending almost the whole saving back defeats the consolidation's purpose.
                    fairDelta += 4; commitDelta += 4; savingsDelta -= 2.0; coachKey = `coach_r4_package_overspend`;
                }

                // Retain the two key engineers needed for the transfer.
                if (d.retain === `role`) {
                    ds.engineersRetained = 2; commitDelta += 10; integrityDelta += 4; coachKey = `coach_r4_retain_role`;
                } else if (d.retain === `bonus`) {
                    ds.engineersRetained = 1; commitDelta += 2; coachKey = `coach_r4_retain_bonus`;
                } else {
                    ds.engineersRetained = 0; commitDelta -= 8;
                    savingsDelta -= 2.0; coachKey = `coach_r4_retain_none`;
                }

                // The EVALUATE stage closes the INVOLVE cycle.
                if (d.evaluate === `loop`) {
                    fairDelta += 10; integrityDelta += 14; commitDelta += 6; coachKey = (d.retain === `role`) ? `coach_r4_loop` : coachKey;
                } else if (d.evaluate === `informal`) {
                    integrityDelta += 2;
                } else {
                    integrityDelta -= 10; coachKey = `coach_r4_noeval`;
                }

                // Customer reassurance — evidence vs silence vs over-promise.
                if (d.customer === `evidence`) {
                    if (ds.engineersRetained === 0) { savingsDelta -= 1.0; coachKey = `coach_r4_cust_hollow`; }
                    else { commitDelta += 4; savingsDelta += 1.0; }
                } else if (d.customer === `silence`) {
                    savingsDelta -= 2.5; coachKey = (coachKey === `coach_default`) ? `coach_r4_cust_silence` : coachKey;
                } else if (d.customer === `overpromise`) {
                    ds.overPromised = true; integrityDelta -= 8; coachKey = (coachKey === `coach_default`) ? `coach_r4_cust_overpromise` : coachKey;
                }

                summaryKey = (pkg >= 3 && d.retain === `role` && d.evaluate === `loop` && d.customer !== `overpromise`) ? `sum_r4_good` : `sum_r4_weak`;
            }

            // Apply deltas with clamps.
            ds.fairness = Math.max(0, Math.min(100, ds.fairness + fairDelta));
            ds.commit = Math.max(0, Math.min(100, ds.commit + commitDelta));
            ds.integrity = Math.max(0, Math.min(100, ds.integrity + integrityDelta));
            ds.savings = Math.round(Math.max(0, Math.min(this.SAVINGS_TARGET, ds.savings + savingsDelta)) * 10) / 10;

            ds.fairnessHistory.push(Math.round(ds.fairness));
            ds.commitHistory.push(Math.round(ds.commit));
            ds.integrityHistory.push(Math.round(ds.integrity));
            ds.savingsHistory.push(ds.savings);

            const coachMsg = window.mySimulation.t(coachKey);
            ds.lastCoach = coachMsg;
            ds.coachMessages.push(coachMsg);
            const coachEl = document.getElementById(`coachText`);
            if (coachEl) coachEl.innerHTML = coachMsg;

            const self = this;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: state.currentPeriod + 1 });
            }, 500);

            var res = {
                period: state.currentPeriod,
                fairness: Math.round(ds.fairness),
                fairnessDelta: Math.round(fairDelta),
                commit: Math.round(ds.commit),
                commitDelta: Math.round(commitDelta),
                integrity: Math.round(ds.integrity),
                integrityDelta: Math.round(integrityDelta),
                savings: ds.savings,
                savingsDelta: Math.round(savingsDelta * 10) / 10,
                freezeRisk: ds.freezeRisk,
                engineersRetained: ds.engineersRetained,
                fraudCommitted: ds.fraudCommitted,
                summary: window.mySimulation.t(summaryKey),
                coach: coachMsg
            };
            // Expose composite to the reporting/grading layer each period (results_utils.php reads
            // domainState.performance.overallScore); period 4 locks the authoritative score.
            ds.performance = { overallScore: this._composite(ds) };
            return res;
        }

