        getChartData(state) {
            const ds = state.domainState;
            const labels = ds.fairnessHistory.map((_, i) => (i === 0 ? `Leak` : `R` + i));
            return {
                fairnessChart: {
                    labels: labels,
                    datasets: [
                        { data: ds.fairnessHistory },
                        { data: ds.commitHistory },
                        { data: ds.integrityHistory },
                        { data: ds.savingsHistory }
                    ]
                }
            };
        }

        // Shared composite (0-100). Single source of truth for the per-period score written to
        // domainState.performance.overallScore (reporting/grading layer) AND the debrief. Weights
        // identical to v1.0.0.
        _composite(ds) {
            var fairness = Math.round(ds.fairness || 0), commit = Math.round(ds.commit || 0), integrity = Math.round(ds.integrity || 0);
            var savings = ds.savings || 0;
            return Math.max(0, Math.min(100, Math.round(fairness * 0.3 + commit * 0.3 + integrity * 0.25 + Math.min(100, (savings / this.SAVINGS_TARGET) * 100) * 0.15)));
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            const ds = window.mySimulation.state.domainState;
            const fairness = Math.round(ds.fairness);
            const commit = Math.round(ds.commit);
            const integrity = Math.round(ds.integrity);
            const savings = ds.savings;

            const rebuilt = fairness >= this.FAIRNESS_BASELINE;       // back to / above the 62% baseline
            const fraud = ds.fraudCommitted;
            const savingsHeld = savings >= 11.0;                       // most of the €14M preserved
            const composite = this._composite(ds);

            const T = (window.mySimulation && typeof window.mySimulation.t === 'function')
                ? function(k, v) { return window.mySimulation.t(k, v); }
                : function(k) { return k; };

            // Grade band -> localized label (thresholds identical to v1.0.0).
            let performanceKey = `grade_faitaccompli`;
            if (rebuilt && commit >= 65 && integrity >= 65 && savingsHeld && !fraud) performanceKey = `grade_fairprocess`;
            else if (fairness >= 52 && integrity >= 55 && savingsHeld && !fraud) performanceKey = `grade_credible`;
            else if (savingsHeld && composite >= 45) performanceKey = `grade_decided`;
            else if (fraud) performanceKey = `grade_fraud`;
            const performance = T(performanceKey);

            const insights = [];
            if (rebuilt && commit >= 65 && !fraud) insights.push(window.mySimulation.t(`insight_fairprocess`));
            else if (fraud) insights.push(window.mySimulation.t(`insight_fraud`));
            else if (integrity < 45) insights.push(window.mySimulation.t(`insight_lowintegrity`));
            else insights.push(window.mySimulation.t(`insight_partial`));

            if (commit < 50) insights.push(window.mySimulation.t(`insight_lowcommit`));
            if (!savingsHeld) insights.push(window.mySimulation.t(`insight_savingslost`));
            if (ds.overPromised) insights.push(window.mySimulation.t(`insight_overpromise`));
            if (ds.engineersRetained < 2) insights.push(window.mySimulation.t(`insight_engineers`));
            if (rebuilt && integrity >= 65 && savingsHeld && !fraud) insights.push(window.mySimulation.t(`insight_balance`));

            return {
                fairness: fairness,
                commit: commit,
                integrity: integrity,
                savings: savings,
                rebuilt: rebuilt,
                composite: composite,
                totalScore: composite,
                overallScore: composite,
                performanceKey: performanceKey,
                performance: performance,
                insights: insights
            };
        }

        formatCompletionMessage(summary) {
            var T = (window.mySimulation && typeof window.mySimulation.t === 'function')
                ? function(k, v) { return window.mySimulation.t(k, v); }
                : function(k) { return k; };
            var s = summary || {};
            var score = (typeof s.totalScore === 'number') ? s.totalScore
                : (typeof s.composite === 'number' ? s.composite : 0);
            var grade = s.performance || (s.performanceKey ? T(s.performanceKey) : '');
            var rebuilt = !!s.rebuilt;
            var badge = rebuilt
                ? '<span class="fp-cm-badge fp-cm-yes">' + T('cm_rebuilt') + '</span>'
                : '<span class="fp-cm-badge fp-cm-no">' + T('cm_notrebuilt') + '</span>';
            var sav = Math.round((s.savings || 0) * 10) / 10;
            var insights = Array.isArray(s.insights) ? s.insights : [];
            var items = insights.map(function(t) { return '<li>' + t + '</li>'; }).join('');
            var metrics = ''
                + '<div class="fp-cm-metric"><span class="fp-cm-mv">' + Math.round(s.fairness||0) + '</span><span class="fp-cm-ml">' + T('cm_m_fairness') + '</span></div>'
                + '<div class="fp-cm-metric"><span class="fp-cm-mv">' + Math.round(s.commit||0) + '</span><span class="fp-cm-ml">' + T('cm_m_commit') + '</span></div>'
                + '<div class="fp-cm-metric"><span class="fp-cm-mv">' + Math.round(s.integrity||0) + '</span><span class="fp-cm-ml">' + T('cm_m_integrity') + '</span></div>'
                + '<div class="fp-cm-metric"><span class="fp-cm-mv">\u20ac' + sav + 'M</span><span class="fp-cm-ml">' + T('cm_m_savings') + '</span></div>';
            return ''
                + '<div class="fp-completion">'
                +   '<div class="fp-cm-head">'
                +     '<div class="fp-cm-score">' + score + '<span class="fp-cm-score-max">/100</span></div>'
                +     '<div class="fp-cm-grade">' + grade + ' ' + badge + '</div>'
                +   '</div>'
                +   '<div class="fp-cm-metrics">' + metrics + '</div>'
                +   '<div class="fp-cm-insights-title">' + T('cm_debrief') + '</div>'
                +   '<ul class="fp-cm-insights">' + items + '</ul>'
                + '</div>';
        }

