        }
    }

    document.addEventListener(`DOMContentLoaded`, () => {
        window.mySimulation = new USF.SimulationFramework();
        window.mySimulation.initialize(new FairProcessAdapter(), {
            simulationType: `fair_process`,
            maxPeriods: 4,
            autoSaveInterval: 30000
        });
